import { deleteSession } from "@/api/client";
import { useSessionDraftStore } from "@/state/sessionDraftStore";

export async function deleteSessionAndDrafts(token: string, sessionID: string) {
  // A failed deletion must leave the user's draft available to retry.
  await deleteSession(token, sessionID);
  useSessionDraftStore.getState().discardSession(sessionID);
}

import assert from "node:assert/strict";
import { afterEach, beforeEach, test } from "node:test";
