const { useDraftStore: drafts } = await server.ssrLoadModule("/src/state/draftStore.ts");
const { configureRemoteAPIBase } = await server.ssrLoadModule("/src/state/apiBase.ts");
const { buildDraftSubmitParts } = await server.ssrLoadModule("/src/lib/submitParts.ts");
const { deleteSessionAndDrafts } = await server.ssrLoadModule("/src/lib/deleteSessionAndDrafts.ts");
let dom: JSDOM, stop: () => void;
const state = () => sessions.getState();
const draftState = () => drafts.getState();
const uploaded = (id: string) => ({ id, name: id + ".png", size: 12, status: "uploaded", previewURL: "blob:expired",
  attachment: { id: "server-" + id, name: id + ".png", size: 12, mime: "image/png", attachmentKey: "blobs/" + id, url: "/attachments/" + id } });
const input = (text = "send this") => ({ text, parts: [{ type: "text", text }], provider: "mock", model: "mock", title: "", reasoningEffort: "" });
const entries = () => Object.fromEntries(Object.entries(dom.window.localStorage));
const stored = () => JSON.stringify(entries());
function restart() {
  stop();
  sessions.setState({ drafts: {}, queueEdits: {} }); drafts.setState({ drafts: {} });
  stop = startDraftPersistence();
}
beforeEach(() => {
  dom = new JSDOM("", { url: "https://relay.example/d/desktop-a/" });
  Object.assign(globalThis, { window: dom.window, document: dom.window.document });
  configureRemoteAPIBase("desktop-a");
  sessions.setState({ drafts: {}, queueEdits: {} }); drafts.setState({ drafts: {} });
  stop = startDraftPersistence();
});
afterEach(() => {
  stop(); dom.window.close();
  Reflect.deleteProperty(globalThis, "window"); Reflect.deleteProperty(globalThis, "document");
});

test("reload restores independent session, new conversation and widget text drafts verbatim", () => {
  state().setText("a", "  中文\nTab suggestion edited 🥳  "); state().setText("b", " ");
  draftState().setText("chat", "New conversation"); draftState().setText("widget:item", "Widget draft");
  restart();
  assert.equal(state().ensure("a").text, "  中文\nTab suggestion edited 🥳  ");
  assert.equal(state().ensure("b").text, " ");
  assert.equal(draftState().drafts.chat.text, "New conversation");
  assert.equal(draftState().drafts["widget:item"].text, "Widget draft");
});

test("text writes are debounced and pagehide flushes the most recent input", async () => {
  state().setText("a", "first");
  state().setText("a", "second"); state().setText("a", "last before debounce");
  assert.ok(!stored().includes("last before debounce"));
  await delay(300);
  assert.ok(stored().includes("last before debounce"));
  state().setText("a", "last before exit");
  dom.window.dispatchEvent(new dom.window.Event("pagehide"));
  assert.ok(stored().includes("last before exit"));
  restart(); assert.equal(state().ensure("a").text, "last before exit");
});

test("only uploaded attachments survive; previews and unfinished bytes never reach storage", () => {
  const items = [uploaded("ready"), { id: "pending", name: "pending.txt", size: 8, status: "uploading", file: new File(["PRIVATE_BYTES"], "pending.txt") },
    { id: "failed", name: "failed.txt", size: 8, status: "error", file: new File(["PRIVATE_BYTES"], "failed.txt"), errorKey: "composer.uploadFailed" }];
  state().setAttachments("a", items); state().setPartOrder("a", items.map(({ id }) => ({ type: "attachment", id })));
  draftState().setAttachments("chat", items); draftState().setPartOrder("chat", items.map(({ id }) => ({ type: "attachment", id })));
