import assert from "node:assert/strict";
import { beforeEach, test } from "node:test";
import { createTestViteServer } from "./vite-test-server.ts";

const server = await createTestViteServer();
const { useSessionDraftStore, queuedDraftKey } = await server.ssrLoadModule("/src/state/sessionDraftStore.ts");
const state = useSessionDraftStore.getState();
beforeEach(() => useSessionDraftStore.setState({ drafts: {}, queueEdits: {} }));

const attachment = (id: string) => ({ id, name: `${id}.png`, size: 10, status: "uploaded", previewURL: `blob:${id}`,
  attachment: { id, name: `${id}.png`, size: 10, mime: "image/png" } });
const folder = (id: string) => ({ id, name: id, path: `/tmp/${id}` });
const reference = (id: string) => ({ id, rootID: "root", path: `${id}.md`, kind: "file" });
const studio = (id: string) => ({ id, kind: "widget", itemID: id, name: id, revision: "v1" });

function seed(key: string) {
  state.setText(key, "  first message\n");
  state.setAttachments(key, [attachment("sent")]);
  state.setLocalFolders(key, [folder("sent-folder")]);
  state.setProjectReferences(key, [reference("sent-reference")]);
  state.setStudioReferences(key, [studio("sent-studio")]);
  state.setPartOrder(key, [
    { type: "attachment", id: "sent" },
    { type: "local_folder", id: "sent-folder" },
    { type: "project_reference", id: "sent-reference" },
  ]);
}

test("an unchanged accepted draft clears once, rotates its ID and releases its previews", (t) => {
  const revoked = t.mock.method(URL, "revokeObjectURL", () => {});
  seed("a");
  const submission = state.prepareSubmission("a");
  state.acknowledgeSubmission("a", submission);
  const next = state.ensure("a");
  assert.equal(next.text, "");
  for (const key of ["attachments", "localFolders", "projectReferences", "studioReferences", "partOrder"]) assert.deepEqual(next[key], []);
  assert.notEqual(next.clientMessageID, submission.clientMessageID);
  assert.deepEqual(revoked.mock.calls.map(call => call.arguments), [["blob:sent"]]);
  state.acknowledgeSubmission("a", submission);
  assert.equal(state.ensure("a"), next, "duplicate acknowledgements have no side effects");
});

test("a delayed acknowledgement retains later text, all new card types, order and live preview URLs", (t) => {
  const revoked = t.mock.method(URL, "revokeObjectURL", () => {});
  seed("a");
  const submission = state.prepareSubmission("a");
  state.setText("a", "later unsent message");
  const pending = { ...attachment("later"), status: "uploading", attachment: undefined };
  state.setAttachments("a", current => [...current, pending]);
  state.setLocalFolders("a", current => [...current, folder("later-folder")]);
  state.setProjectReferences("a", current => [...current, reference("later-reference")]);
  state.setStudioReferences("a", current => [...current, studio("later-studio")]);
  const order = [{ type: "project_reference", id: "later-reference" }, { type: "attachment", id: "later" }, { type: "local_folder", id: "later-folder" }];
  state.setPartOrder("a", current => [...current, ...order]);
  state.acknowledgeSubmission("a", submission);
  const next = state.ensure("a");
  assert.equal(next.text, "later unsent message");
  assert.deepEqual(next.attachments, [pending]);
  assert.deepEqual(next.localFolders, [folder("later-folder")]);
  assert.deepEqual(next.projectReferences, [reference("later-reference")]);
  assert.deepEqual(next.studioReferences, [studio("later-studio")]);
  assert.deepEqual(next.partOrder, order);
  assert.deepEqual(revoked.mock.calls.map(call => call.arguments), [["blob:sent"]]);
  state.setAttachments("a", current => current.map(item => item.id === pending.id ? attachment("later") : item));
  const second = state.prepareSubmission("a");
  assert.notEqual(second.clientMessageID, submission.clientMessageID);
  assert.equal(second.attachments[0].status, "uploaded");
});

test("replacing a card under the same ID retains the edited version", () => {
  seed("a");
  const submission = state.prepareSubmission("a");
  const edited = { ...submission.studioReferences[0], revision: "v2", selectedText: "new selection" };
  state.setStudioReferences("a", [edited]);
  state.acknowledgeSubmission("a", submission);
  assert.deepEqual(state.ensure("a").studioReferences, [edited]);
});

test("failed or lost responses reuse an unchanged ID; editing submitted content creates a fresh request", () => {
  for (const edit of [
    () => state.setText("a", "changed"),
    () => state.setAttachments("a", []),
    () => state.setLocalFolders("a", []),
    () => state.setProjectReferences("a", []),
    () => state.setStudioReferences("a", []),
    () => state.setPartOrder("a", current => [...current].reverse()),
  ]) {
    state.clear("a"); seed("a");
    const original = state.prepareSubmission("a");
    state.setText("a", original.text);
    assert.equal(state.prepareSubmission("a"), original, "unchanged retries are idempotent");
    edit();
    const changed = state.prepareSubmission("a");
    assert.notEqual(changed.clientMessageID, original.clientMessageID);
    state.acknowledgeSubmission("a", original);
    assert.equal(state.ensure("a").submission, changed, "old acknowledgements cannot consume a newer submission");
    assert.equal(state.prepareSubmission("a"), changed);
  }
});

test("late responses only affect their original conversation draft, including when a queue edit is visible", () => {
  state.setText("a", "sent from A");
  const submitted = state.prepareSubmission("a");
  state.setText("b", "B unsent");
  state.beginQueueEdit("a", { clientMessageID: "queued", text: "queued edit", parts: [] });
  state.setText("a", "A later draft");
  state.acknowledgeSubmission("a", submitted);
  assert.equal(state.ensure("a").text, "A later draft");
  assert.equal(state.ensure("b").text, "B unsent");
  assert.equal(state.ensure(queuedDraftKey("a", "queued")).text, "queued edit");
  assert.equal(useSessionDraftStore.getState().queueEdits.a, "queued");
});

test("explicit clearing or removal invalidates outstanding acknowledgements", () => {
  state.setText("a", "sent");
  const submitted = state.prepareSubmission("a");
  state.clear("a");
  state.setText("a", "replacement draft");
  const replacement = state.ensure("a");
  state.acknowledgeSubmission("a", submitted);
  assert.equal(state.ensure("a"), replacement);
  useSessionDraftStore.setState({ drafts: {} });
  state.acknowledgeSubmission("a", submitted);
  assert.deepEqual(useSessionDraftStore.getState().drafts, {});
});

