const body = "Long pasted content\n".repeat(300);
const reply = (file: File) => Response.json({ id: "server-" + file.name, name: file.name,
  size: file.size, mime: file.type, attachmentKey: "stored-" + file.name, url: "/attachment/" + file.name });
const fail = () => Response.json({ error: "unavailable" }, { status: 503 });
const pending = () => {
  let resolve!: (response: Response) => void;
  const promise = new Promise<Response>(done => { resolve = done; });
  return { promise, resolve };
};
beforeEach(() => {
  useDraftStore.setState({ drafts: {} });
  useSessionDraftStore.setState({ drafts: {}, queueEdits: {} });
});
for (const [label, store, key, sessionID] of [
