    setAttachments: update => store.getState().setAttachments(key, update),
    setPartOrder: update => store.getState().setPartOrder(key, update), onError: item => errors.push(item) });
  test(`${label}: failure preserves bytes/order; retry sends original target/options once`, async t => {
    const calls: { url: string; form: FormData }[] = [], errors: unknown[] = [], held = pending();
    t.mock.method(globalThis, "fetch", async (url, init) => {
      calls.push({ url: String(url), form: init.body });
      if (calls.length === 1) throw new TypeError("offline");
      return held.promise;
    });
    const uploader = make(errors), file = new File([body], "pasted.txt", { type: "text/plain" });
    store.getState().setText(key, "keep typing");
    uploader.addFiles([file], { origin: "temp", uploadSessionID: "draft", sourcePaths: ["/tmp/original.txt"] });
    const id = current().attachments[0].id, order = current().partOrder;
    await setImmediate();
    const failed = current().attachments[0];
    assert.equal(failed.status, "error"); assert.equal(failed.file, file);
    assert.equal(await failed.file.text(), body); assert.equal(errors.length, 1);
    assert.equal(current().partOrder, order);
    uploader.retryAttachment(id); uploader.retryAttachment(id);
    assert.equal(current().attachments[0].status, "uploading"); assert.equal(calls.length, 2);
    for (const call of calls) {
      assert.ok(call.url.endsWith("/sessions/draft/attachments"));
      assert.equal(call.form.get("origin"), "temp"); assert.equal(call.form.get("sourcePath"), "/tmp/original.txt");
      assert.equal(await (call.form.get("file") as File).text(), body);
    }
    store.getState().setText("other", "other draft"); store.getState().setText(key, "later text");
    held.resolve(reply(file)); await setImmediate();
    const saved = current().attachments[0];
    assert.equal(saved.status, "uploaded"); assert.equal(saved.id, id);
    assert.equal(saved.file, undefined); assert.equal(saved.upload, undefined);
    assert.equal(current().partOrder, order); assert.equal(current().text, "later text");
    assert.equal(store.getState().drafts.other.text, "other draft");
    const parts = buildDraftSubmitParts("", current().attachments, [], order);
    assert.equal(parts.length, 1); assert.equal(parts[0].attachmentKey, "stored-pasted.txt");
    uploader.retryAttachment(id); assert.equal(calls.length, 2);
  });
  test(`${label}: removed/replaced/deleted drafts reject late responses without recreation`, async t => {
    const errors: unknown[] = [], gates: ReturnType<typeof pending>[] = [];
    t.mock.method(globalThis, "fetch", () => { const gate = pending(); gates.push(gate); return gate.promise; });
    t.mock.method(URL, "createObjectURL", () => "blob:preview");
    const revoked = t.mock.method(URL, "revokeObjectURL", () => {});
    const uploader = make(errors), file = new File(["image"], "image.png", { type: "image/png" });
    uploader.addFiles([file]); const old = current().attachments[0], replacement = { ...old, status: "error" };
    store.getState().setAttachments(key, [replacement]);
    gates[0].resolve(reply(file)); await setImmediate();
    assert.equal(current().attachments[0], replacement);
    uploader.retryAttachment(old.id); store.getState().setAttachments(key, []); store.getState().setPartOrder(key, []);
    gates[1].resolve(fail()); await setImmediate();
    assert.deepEqual(current().attachments, []); assert.deepEqual(errors, []);
    for (const response of [reply(file), fail()]) {
      uploader.addFiles([file]); store.setState({ drafts: {} }); const state = store.getState();
      gates.at(-1)!.resolve(response); await setImmediate();
      assert.equal(store.getState(), state); assert.deepEqual(store.getState().drafts, {});
    }
    assert.equal(revoked.mock.callCount(), 0); // Preview cleanup belongs to removal/acknowledgement.
  });
}

