import assert from "node:assert/strict";
import { beforeEach, test } from "node:test";
import { QueryClient } from "@tanstack/react-query";
import { createTestViteServer } from "./vite-test-server.ts";

const server = await createTestViteServer();
const { useDraftStore } = await server.ssrLoadModule("/src/state/draftStore.ts");
const { submitDraftConversation } = await server.ssrLoadModule("/src/components/DraftConversation.tsx");
const { buildDraftSubmitParts } = await server.ssrLoadModule("/src/lib/submitParts.ts");
const { useOverlayStore } = await server.ssrLoadModule("/src/state/overlayStore.ts");
const state = useDraftStore.getState();
const content = (key = "chat") => useDraftStore.getState().drafts[key];
const attachment = (id: string) => ({ id, name: `${id}.png`, size: 4, status: "uploaded", previewURL: `blob:${id}`,
  attachment: { id, name: `${id}.png`, attachmentKey: id, url: `/sessions/draft/attachments/${id}/image.png`, size: 4, mime: "image/png" } });
const folder = (id: string) => ({ id, name: id, path: `/tmp/${id}` });
function seed(key = "chat") {
  state.setText(key, "  first message\n");
  state.setAttachments(key, [attachment("sent")]);
  state.setLocalFolders(key, [folder("sent-folder")]);
  state.setPartOrder(key, [{ type: "attachment", id: "sent" }, { type: "local_folder", id: "sent-folder" }]);
}
function prepare(key = "chat") {
  const draft = content(key), text = draft.text.trim();
  return state.prepareSubmission(key, { text, parts: buildDraftSubmitParts(text, draft.attachments, draft.localFolders, draft.partOrder),
    provider: "mock", model: "mock", projectID: "project", reasoningEffort: "high", title: "" });
}
beforeEach(() => { useDraftStore.setState({ drafts: {} }); useOverlayStore.setState(useOverlayStore.getInitialState(), true); });

test("unchanged first draft clears exactly once, including raw whitespace, cards and creation identity", (t) => {
  const revoked = t.mock.method(URL, "revokeObjectURL", () => {});
  seed(); const sent = prepare();
  const remaining = state.acknowledgeSubmission("chat", sent);
  assert.deepEqual(remaining, { text: "", attachments: [], localFolders: [], partOrder: [] });
  assert.deepEqual(revoked.mock.calls.map(call => call.arguments), [["blob:sent"]]);
  assert.equal(state.acknowledgeSubmission("chat", sent), undefined);
  assert.equal(content(), remaining);
  seed(); const next = prepare();
  assert.notEqual(next.clientRequestID, sent.clientRequestID);
  assert.notEqual(next.clientMessageID, sent.clientMessageID);
});

test("acknowledgement retains later text, uploading files, folders and their current order; releases only removed previews", (t) => {
  const revoked = t.mock.method(URL, "revokeObjectURL", () => {});
  seed(); const sent = prepare();
  state.setText("chat", "later unsent text");
  const pending = { ...attachment("later"), status: "uploading", attachment: undefined };
  state.setAttachments("chat", items => [...items, pending]);
  state.setLocalFolders("chat", items => [...items, folder("later-folder")]);
  const order = [{ type: "local_folder", id: "later-folder" }, { type: "attachment", id: "later" }];
  state.setPartOrder("chat", [...order, ...content().partOrder]);
  state.acknowledgeSubmission("chat", sent);
  assert.equal(content().text, "later unsent text");
  assert.deepEqual(content().attachments, [pending]);
  assert.deepEqual(content().localFolders, [folder("later-folder")]);
  assert.deepEqual(content().partOrder, order);
  assert.deepEqual(revoked.mock.calls.map(call => call.arguments), [["blob:sent"]]);
  state.setAttachments("chat", items => items.map(item => item.id === "later" ? attachment("later") : item));
  const next = prepare();
  assert.notEqual(next.clientRequestID, sent.clientRequestID);
  assert.equal(next.input.parts[1].name, "later.png");
});

test("replaced cards with the same IDs survive an old acknowledgement", (t) => {
  const revoked = t.mock.method(URL, "revokeObjectURL", () => {});
  seed(); const sent = prepare();
  const replacement = { ...content().attachments[0], attachment: { ...content().attachments[0].attachment, name: "edited.png" } };
  const editedFolder = { ...content().localFolders[0], path: "/tmp/edited" };
  state.setAttachments("chat", [replacement]); state.setLocalFolders("chat", [editedFolder]);
  state.acknowledgeSubmission("chat", sent);
  assert.equal(content().text, "");
  assert.deepEqual(content().attachments, [replacement]);
  assert.deepEqual(content().localFolders, [editedFolder]);
  assert.equal(content().partOrder.length, 2);
  assert.equal(revoked.mock.callCount(), 0);
});

test("failure retries keep B07 identities but only the latest snapshot can acknowledge the draft", () => {
  seed(); const first = prepare(), retry = prepare();
  assert.equal(retry.clientRequestID, first.clientRequestID);
  assert.equal(retry.clientMessageID, first.clientMessageID);
  assert.equal(state.acknowledgeSubmission("chat", first), undefined);
  state.setText("chat", "corrected request"); const edited = prepare();
  assert.equal(edited.clientRequestID, first.clientRequestID);
  assert.notEqual(edited.clientMessageID, first.clientMessageID);
  assert.equal(state.acknowledgeSubmission("chat", retry), undefined);
  state.setText("chat", "new draft while retrying"); state.acknowledgeSubmission("chat", edited);
  assert.equal(content().text, "new draft while retrying");
});

test("responses stay scoped to their draft entry and cannot clear an explicitly reset or removed draft", () => {
  seed(); seed("widget:new"); const sent = prepare();
  const widget = content("widget:new"); state.setText("chat", "later");
  state.acknowledgeSubmission("chat", sent); assert.equal(content("widget:new"), widget);
  const next = prepare(); state.clear("chat"); state.setText("chat", "fresh replacement");
  const fresh = content(); state.acknowledgeSubmission("chat", next); assert.equal(content(), fresh);
  const removed = prepare(); useDraftStore.setState({ drafts: {} });
  state.acknowledgeSubmission("chat", removed); assert.deepEqual(useDraftStore.getState().drafts, {});
});

for (const phase of ["create", "configure", "submit", "refresh"]) {
  test(`later edits made during ${phase} survive the full first-submit success path`, async () => {
    seed(); const sent = prepare();
    const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
    const stamp = "2026-10-13T00:00:00Z";
    let created = { id: "created", title: "", provider: "mock", model: "mock", projectID: "project", activeMode: "code", modeLease: "session", pinned: false, pinnedOrder: 0, createdAt: stamp, updatedAt: stamp, lastActivityAt: stamp, running: false, backgroundProcessCount: 0 };
    const held = Promise.withResolvers<void>(), released = Promise.withResolvers<void>();
    const hold = async (stage: string) => { if (stage === phase) { held.resolve(); await released.promise; } };
    const previous = globalThis.fetch;
    let navigations = 0;
    globalThis.fetch = async (url, init) => {
      const path = String(url), body = init?.body ? JSON.parse(String(init.body)) : {};
      if (path.endsWith("/sessions")) { await hold("create"); return Response.json(created); }
      if (init?.method === "PATCH") { await hold("configure"); created = { ...created, ...body }; return Response.json(created); }
      assert.ok(path.endsWith("/submit"));
      assert.equal(body.text, "first message"); assert.equal(body.clientMessageID, sent.clientMessageID);
      await hold("submit"); return Response.json({ queued: true, status: "queued", clientMessageID: sent.clientMessageID });
    };
    client.invalidateQueries = async () => { await hold("refresh"); };
    try {
      const request = submitDraftConversation({ draftKey: "chat", submission: sent, token: "fixture", queryClient: client, navigate: async () => { navigations++; } });
      await held.promise;
      state.setText("chat", `typed during ${phase}`);
      state.setAttachments("chat", items => [...items, attachment("later")]);
      state.setPartOrder("chat", items => [...items, { type: "attachment", id: "later" }]);
      released.resolve(); await request;
      assert.equal(content().text, `typed during ${phase}`);
      assert.equal(content().attachments[0].id, "later"); assert.equal(content().attachments.length, 1);
      assert.equal(navigations, 0, "keep the later draft visible instead of switching away");
      assert.equal(content().submission, undefined);
    } finally { released.resolve(); globalThis.fetch = previous; client.clear(); }
  });
}

for (const status of ["completed", "running"]) {
  test(`a ${status} initial turn reconciles without mounting its transcript when later edits keep the draft open`, async () => {
    seed(); const sent = prepare();
    const client = new QueryClient();
    const stamp = "2026-10-13T00:00:00Z";
    const created = { id: "created", title: "", provider: "mock", model: "mock", reasoningEffort: "high", projectID: "project", activeMode: "code", modeLease: "session", pinned: false, pinnedOrder: 0, createdAt: stamp, updatedAt: stamp, lastActivityAt: stamp, running: false, backgroundProcessCount: 0 };
    const turn = { id: "turn", sessionID: "created", clientMessageID: sent.clientMessageID, status, createdAt: stamp, updatedAt: stamp,
      messages: [{ id: "user", sessionID: "created", turnID: "turn", clientMessageID: sent.clientMessageID, role: "user", kind: "text", text: sent.input.text, parts: sent.input.parts, turnIndex: 0, createdAt: stamp }] };
    const previous = globalThis.fetch;
    globalThis.fetch = async (url) => {
      const path = String(url);
      if (path.endsWith("/sessions")) return Response.json(created);
      if (path.endsWith("/submit")) {
        state.setText("chat", "later draft");
        return Response.json({ turnID: "turn", clientMessageID: sent.clientMessageID });
      }
      assert.ok(path.endsWith("/turns/turn")); return Response.json(turn);
    };
    try {
      await submitDraftConversation({ draftKey: "chat", submission: sent, token: "fixture", queryClient: client, navigate: async () => assert.fail("later draft must stay visible") });
      assert.equal(content().text, "later draft");
      const overlay = useOverlayStore.getState();
      assert.deepEqual(overlay.pendingUsers.created, []);
      assert.equal(Boolean(overlay.turnPhases.created), status === "running", "a completed snapshot must retire the background subscription; a running one must remain active");
    } finally { globalThis.fetch = previous; client.clear(); }
  });
}

