  assert.equal(state.acknowledgeQueueEdit("a", "queued", snapshot), true);
  assert.equal(current(), undefined); assert.equal(useSessionDraftStore.getState().queueEdits.a, undefined);
  assert.equal(state.ensure("a").text, "independent ordinary draft"); assert.equal(state.ensure("b").text, "other session");
  assert.equal(state.acknowledgeQueueEdit("a", "queued", snapshot), false);
  assert.deepEqual(revoked.mock.calls.map(call => call.arguments), [["blob:saved"]]);
});

for (const [label, edit] of [
  ["later text", () => state.setText(key, "later text")],
  ["pending attachment", () => state.setAttachments(key, items => [...items, { id: "later", name: "later.txt", size: 3, status: "uploading", file: new File(["abc"], "later.txt") }])],
  ["removed attachment", () => state.setAttachments(key, [])],
  ["replaced attachment", () => state.setAttachments(key, [attachment("saved")])],
  ["folder", () => state.setLocalFolders(key, [])],
  ["project reference", () => state.setProjectReferences(key, [])],
  ["Studio reference revision", () => state.setStudioReferences(key, items => [{ ...items[0], revision: "v2" }])],
  ["part order", () => state.setPartOrder(key, items => [...items].reverse())],
] as const) {
