// Package widget validates immutable, generated widget source packages.
// Generated code is never evaluated by Core.
package widget

import (
	"bytes"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"net/url"
	"path"
	"regexp"
	"strconv"
	"strings"
	"unicode/utf8"

	"github.com/teatak/pudding-core/contracts"
)

// ManifestFile declares a widget package's entry, plugin sources and operations.
const ManifestFile = "widget.json"

var identifier = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9_-]{0,79}$`)
var sourceFileName = regexp.MustCompile(`^[a-zA-Z0-9_./ -]+$`)
var revisionID = regexp.MustCompile(`^[a-f0-9]{64}$`)
var graphqlUnsafeOperation = regexp.MustCompile(`\b(mutation|subscription)\b`)

type Source struct {
	PluginID string `json:"pluginID"`
	Endpoint string `json:"endpoint"`
}
type Request struct {
	Method        string         `json:"method,omitempty"`
	Path          string         `json:"path,omitempty"`
	PathParams    map[string]any `json:"pathParams,omitempty"`
	Query         map[string]any `json:"query,omitempty"`
	Body          any            `json:"body,omitempty"`
	Document      string         `json:"document,omitempty"`
	OperationName string         `json:"operationName,omitempty"`
	Variables     map[string]any `json:"variables,omitempty"`
}
type Result struct {
	Rows    string         `json:"rows,omitempty"`
	Total   string         `json:"total,omitempty"`
	Cursor  string         `json:"cursor,omitempty"`
	Schema  map[string]any `json:"schema,omitempty"`
	Success *Condition     `json:"success,omitempty"`
}
type Condition struct {
	Pointer string `json:"pointer"`
	Equals  any    `json:"equals"`
}
type Operation struct {
	Source      string         `json:"source"`
	Kind        string         `json:"kind"`
	EffectHint  string         `json:"effectHint"`
	Description string         `json:"description,omitempty"`
	InputSchema map[string]any `json:"inputSchema"`
	Request     Request        `json:"request"`
	Result      Result         `json:"result,omitempty"`
}
type Manifest struct {
	SchemaVersion int                  `json:"schemaVersion"`
	SDKVersion    string               `json:"sdkVersion"`
	Entry         string               `json:"entry"`
	Sources       map[string]Source    `json:"sources"`
	Operations    map[string]Operation `json:"operations"`
}
type Package struct {
	Files map[string]string `json:"files"`
}

func DecodeStrict(data []byte, target any) error {
	d := json.NewDecoder(bytes.NewReader(data))
	d.DisallowUnknownFields()
	if err := d.Decode(target); err != nil {
		return err
	}
	if err := d.Decode(new(any)); err != io.EOF {
		return errors.New("expected one JSON value")
	}
	return nil
}

func (p Package) Validate() (Manifest, string, error) {
	var m Manifest
	policy := contracts.Widget()
	if len(p.Files) == 0 || len(p.Files) > policy.MaxFiles {
		return m, "", errors.New("invalid package file count")
	}
	total := 0
	for name, content := range p.Files {
		if !ValidFilePath(name) || !utf8.ValidString(content) {
			return m, "", fmt.Errorf("invalid source file %q", name)
		}
		total += len(content)
		if len(content) > policy.MaxFileBytes || total > policy.MaxPackageBytes {
			return m, "", errors.New("package exceeds size limit")
		}
	}
	if err := DecodeStrict([]byte(p.Files[ManifestFile]), &m); err != nil {
		return m, "", fmt.Errorf("widget.json: %w", err)
	}
	if m.SchemaVersion != policy.SchemaVersion || m.SDKVersion != policy.SDKVersion {
		return m, "", errors.New("unsupported widget or SDK version")
	}
	if !strings.HasPrefix(m.Entry, "src/") || !strings.HasSuffix(m.Entry, ".tsx") || p.Files[m.Entry] == "" {
		return m, "", errors.New("entry must reference an existing src/*.tsx file")
	}
	if len(m.Sources) > policy.MaxSources || len(m.Operations) > policy.MaxOperations {
		return m, "", errors.New("too many sources or operations")
	}
	for id, source := range m.Sources {
		if !identifier.MatchString(id) || !identifier.MatchString(source.PluginID) || !identifier.MatchString(source.Endpoint) {
			return m, "", fmt.Errorf("invalid source %q", id)
		}
	}
	for id, op := range m.Operations {
		if !identifier.MatchString(id) {
			return m, "", fmt.Errorf("invalid operation %q", id)
		}
		if _, ok := m.Sources[op.Source]; !ok {
			return m, "", fmt.Errorf("operation %q references missing source", id)
		}
		if err := op.Validate(); err != nil {
			return m, "", fmt.Errorf("operation %s: %w", id, err)
		}
	}
	data, err := json.Marshal(p)
	if err != nil {
		return m, "", err
	}
	return m, fmt.Sprintf("%x", sha256.Sum256(data)), nil
}

func ValidFilePath(name string) bool {
	if !sourceFileName.MatchString(name) || len(name) > 240 || strings.ContainsAny(name, "\\\x00") || path.Clean(name) != name || strings.HasPrefix(name, "/") {
		return false
	}
	if name == ManifestFile {
		return true
	}
	if !strings.HasPrefix(name, "src/") && !strings.HasPrefix(name, "fixtures/") && !strings.HasPrefix(name, "assets/") {
		return false
	}
	switch path.Ext(name) {
	case ".ts", ".tsx", ".css", ".json", ".svg":
		return true
	}
	return false
}

func (o Operation) Validate() error {
	if o.EffectHint != "read" && o.EffectHint != "write" && o.EffectHint != "unknown" {
		return errors.New("effectHint must be read, write or unknown")
	}
	if err := ValidateSchema(o.InputSchema); err != nil {
		return fmt.Errorf("inputSchema: %w", err)
	}
	if o.InputSchema["type"] != "object" {
		return errors.New("inputSchema must describe an object")
	}
	if len(o.Result.Schema) != 0 {
		if err := ValidateSchema(o.Result.Schema); err != nil {
			return err
		}
	}
	for _, pointer := range []string{o.Result.Rows, o.Result.Total, o.Result.Cursor} {
		if !ValidPointer(pointer) {
			return errors.New("invalid result JSON pointer")
		}
	}
	if o.Result.Success != nil && !ValidPointer(o.Result.Success.Pointer) {
		return errors.New("invalid success JSON pointer")
	}
	switch o.Kind {
	case "rest":
		if o.Request.Method != "GET" && o.Request.Method != "POST" && o.Request.Method != "PUT" && o.Request.Method != "PATCH" && o.Request.Method != "DELETE" {
			return errors.New("unsupported REST method")
		}
		if err := validateRelativePath(o.Request.Path); err != nil {
			return err
		}
		if o.Request.Document != "" || o.Request.OperationName != "" || len(o.Request.Variables) > 0 {
			return errors.New("GraphQL fields in REST operation")
		}
	case "graphql":
		if strings.TrimSpace(o.Request.Document) == "" || strings.TrimSpace(o.Request.OperationName) == "" {
			return errors.New("GraphQL document and operationName required")
		}
		if o.Request.Path != "" || o.Request.Method != "" || o.Request.Body != nil || len(o.Request.PathParams)+len(o.Request.Query) > 0 {
			return errors.New("REST fields in GraphQL operation")
		}
	default:
		return errors.New("unsupported operation kind")
	}
	_, err := transform(o.Request, nil, true)
	return err
}

func validateRelativePath(value string) error {
	u, err := url.Parse(value)
	if err != nil || value == "" || u.IsAbs() || u.Host != "" || u.RawQuery != "" || u.Fragment != "" || strings.HasPrefix(value, "//") || strings.Contains(value, "\\") {
		return errors.New("path must stay within the plugin endpoint")
	}
	for _, segment := range strings.Split(u.Path, "/") {
		if segment == ".." || segment == "." {
			return errors.New("path traversal is not allowed")
		}
	}
	return nil
}

func (o Operation) Hash() string { b, _ := json.Marshal(o); return fmt.Sprintf("%x", sha256.Sum256(b)) }

// SafeRead permits automatic refresh only for requests whose transport has
// read semantics. effectHint is generated source and cannot authorize a write.
func (o Operation) SafeRead() bool {
	if o.EffectHint != "read" {
		return false
	}
	if o.Kind == "rest" {
		return o.Request.Method == "GET" && o.Request.Body == nil
	}
	if o.Kind != "graphql" {
		return false
	}
	document := strings.TrimSpace(o.Request.Document)
	return (strings.HasPrefix(document, "query ") || strings.HasPrefix(document, "query\n") || strings.HasPrefix(document, "query(") || strings.HasPrefix(document, "{") || document == "query") && !graphqlUnsafeOperation.MatchString(document)
}

// ResolveRequest only substitutes declared values; it never evaluates expressions.
func (o Operation) ResolveRequest(input map[string]any) (Request, error) {
	if err := ValidateInput(o.InputSchema, input); err != nil {
		return Request{}, err
	}
	value, err := transform(o.Request, input, false)
	if err != nil {
		return Request{}, err
	}
	b, _ := json.Marshal(value)
	var r Request
	if err = json.Unmarshal(b, &r); err != nil {
		return r, err
	}
	for key, value := range r.PathParams {
		var text string
		switch v := value.(type) {
		case string:
			text = v
		case float64:
			if math.Trunc(v) != v || math.Abs(v) > 1<<53-1 {
				return r, errors.New("path parameters must be nonempty strings or safe integers without dot segments")
			}
			text = strconv.FormatFloat(v, 'f', 0, 64)
		default:
			return r, errors.New("path parameters must be nonempty strings or safe integers without dot segments")
		}
		if text == "" || text == "." || text == ".." {
			return r, errors.New("path parameters must be nonempty strings or safe integers without dot segments")
		}
		r.Path = strings.ReplaceAll(r.Path, "{"+key+"}", url.PathEscape(text))
	}
	if o.Kind == "rest" {
		if strings.ContainsAny(r.Path, "{}") {
			return r, errors.New("unresolved path parameter")
		}
		if err = validateRelativePath(r.Path); err != nil {
			return r, err
		}
	}
	return r, nil
}

func transform(request Request, input map[string]any, validate bool) (any, error) {
	b, err := json.Marshal(request)
	if err != nil {
		return nil, err
	}
	var value any
	if err = json.Unmarshal(b, &value); err != nil {
		return nil, err
	}
	return transformValue(value, input, validate, 0)
}

func transformValue(value any, input map[string]any, validate bool, depth int) (any, error) {
	if depth > contracts.Widget().MaxSchemaDepth {
		return nil, errors.New("request template too deep")
	}
	switch v := value.(type) {
	case map[string]any:
		if pointer, ok := v["$input"]; ok {
			p, ok := pointer.(string)
			if !ok || !ValidPointer(p) || len(v) != 1 {
				return nil, errors.New("invalid $input reference")
			}
			if validate {
				return v, nil
			}
			return Pointer(input, p)
		}
		for k, child := range v {
			out, err := transformValue(child, input, validate, depth+1)
			if err != nil {
				return nil, err
			}
			v[k] = out
		}
	case []any:
		for i, child := range v {
			out, err := transformValue(child, input, validate, depth+1)
			if err != nil {
				return nil, err
			}
			v[i] = out
		}
	}
	return value, nil
}

files.core/internal/widget/draft.go:
package widget

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"unicode/utf8"

	"github.com/teatak/pudding-core/contracts"
)

var ErrDraftConflict = errors.New("widget draft changed")

// DraftMu serializes draft edits and commits within the daemon. A tool edit
// must not race the HTTP draft/commit path after checking expectedDraftHash.
var DraftMu sync.Mutex

// Draft is the mutable working copy. Only a committed revision is usable by the runtime.
type Draft struct {
	BaseRevisionHash string            `json:"baseRevisionHash"`
	DraftHash        string            `json:"draftHash"`
	Files            map[string]string `json:"-"`
}

func DraftRoot(home, id string) (string, error) {
	if home == "" || !identifier.MatchString(id) {
		return "", errors.New("invalid widget draft reference")
	}
	return filepath.Join(home, "studio", id, "draft"), nil
}

func ReadDraft(home, id string) (Draft, error) {
	root, err := DraftRoot(home, id)
	if err != nil {
		return Draft{Files: map[string]string{}}, err
	}
	return ReadDraftDir(root, ValidFilePath)
}

// ReadDraftDir reads one working copy, whose files may be incomplete.
func ReadDraftDir(root string, validPath func(string) bool) (Draft, error) {
	d := Draft{Files: map[string]string{}}
	base, err := os.ReadFile(filepath.Join(root, ".base"))
	if err != nil {
		return d, err
	}
	d.BaseRevisionHash = string(base)
	if d.BaseRevisionHash != "" && !revisionID.MatchString(d.BaseRevisionHash) {
		return d, errors.New("invalid draft base revision")
	}
	total := 0
	err = filepath.WalkDir(root, func(file string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.Type()&os.ModeSymlink != 0 {
			return errors.New("symlinks are not allowed in drafts")
		}
		if skipFinderMetadata(entry) {
			return nil
		}
		if entry.IsDir() || file == filepath.Join(root, ".base") {
			return nil
		}
		name, err := filepath.Rel(root, file)
		if err != nil {
			return err
		}
		name = filepath.ToSlash(name)
		if !validPath(name) {
			return fmt.Errorf("invalid draft path %q", name)
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		policy := contracts.Widget()
		total += int(info.Size())
		if !info.Mode().IsRegular() || info.Size() > int64(policy.MaxFileBytes) || total > policy.MaxPackageBytes || len(d.Files) >= policy.MaxFiles {
			return errors.New("draft exceeds file limits")
		}
		content, err := os.ReadFile(file)
		if err != nil {
			return err
		}
		if !utf8.Valid(content) {
			return fmt.Errorf("invalid UTF-8 in %q", name)
		}
		d.Files[name] = string(content)
		return nil
	})
	if err != nil {
		return d, err
	}
	d.DraftHash = draftHash(d.Files)
	return d, nil
}

func draftHash(files map[string]string) string {
	return PackageHash(files)
}

func StartDraft(home, id, baseHash string) (Draft, error) {
	root, err := DraftRoot(home, id)
	if err != nil {
		return Draft{}, err
	}
	if existing, err := ReadDraft(home, id); err == nil {
		return existing, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return Draft{}, err
	}
	files := map[string]string{}
	if baseHash != "" {
		base, err := ReadPackage(home, id, baseHash)
		if err != nil {
			return Draft{}, err
		}
		files = base.Files
	}
	if err := InstallDraft(root, baseHash, files); err != nil {
		return Draft{}, err
	}
	return ReadDraft(home, id)
}

// InstallDraft atomically creates a working copy at root; root must not exist.
func InstallDraft(root, baseHash string, files map[string]string) error {
	parent := filepath.Dir(root)
	if err := os.MkdirAll(parent, 0700); err != nil {
		return err
	}
	staging, err := os.MkdirTemp(parent, ".draft-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(staging)
	if err := os.WriteFile(filepath.Join(staging, ".base"), []byte(baseHash), 0600); err != nil {
		return err
	}
	for name, content := range files {
		file := filepath.Join(staging, filepath.FromSlash(name))
		if err := os.MkdirAll(filepath.Dir(file), 0700); err != nil {
			return err
		}
		if err := os.WriteFile(file, []byte(content), 0600); err != nil {
			return err
		}
	}
	return os.Rename(staging, root)
}

func WriteDraftFile(home, id, name string, content *string, expectedHash string) (Draft, error) {
	d, err := ReadDraft(home, id)
	if err != nil {
		return d, err
	}
	if d.DraftHash != expectedHash {
		return d, ErrDraftConflict
	}
	if !ValidFilePath(name) || (content != nil && strings.HasPrefix(name, "fixtures/")) {
		return d, errors.New("invalid changed source path")
	}
	if content == nil {
		delete(d.Files, name)
	} else {
		d.Files[name] = *content
	}
	policy := contracts.Widget()
	if len(d.Files) > policy.MaxFiles {
		return d, errors.New("draft exceeds file count")
	}
	total := 0
	for path, value := range d.Files {
		total += len(value)
		if !ValidFilePath(path) || !utf8.ValidString(value) || len(value) > policy.MaxFileBytes || total > policy.MaxPackageBytes {
			return d, errors.New("draft exceeds source limits")
		}
	}
	root, _ := DraftRoot(home, id)
	file := filepath.Join(root, filepath.FromSlash(name))
	if content == nil {
		if err := os.Remove(file); err != nil && !errors.Is(err, os.ErrNotExist) {
			return d, err
		}
	} else {
		if err := os.MkdirAll(filepath.Dir(file), 0700); err != nil {
			return d, err
		}
		if err := writeDraftAtomic(root, file, []byte(*content)); err != nil {
			return d, err
		}
	}
	return ReadDraft(home, id)
}

func SetDraftBase(home, id, baseHash string) (Draft, error) {
	if !revisionID.MatchString(baseHash) {
		return Draft{}, errors.New("invalid draft base revision")
	}
	root, err := DraftRoot(home, id)
	if err != nil {
		return Draft{}, err
	}
	if err := writeDraftAtomic(root, filepath.Join(root, ".base"), []byte(baseHash)); err != nil {
		return Draft{}, err
	}
	return ReadDraft(home, id)
}

func writeDraftAtomic(root, file string, data []byte) error {
	parent := filepath.Dir(file)
	f, err := os.CreateTemp(filepath.Dir(root), ".draft-write-")
	if err != nil {
		return err
	}
	defer os.Remove(f.Name())
	if err := f.Chmod(0600); err != nil {
		f.Close()
		return err
	}
	if _, err := f.Write(data); err != nil {
		f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	if err := renamePublication(f.Name(), file); err != nil {
		return err
	}
	return syncPublication(parent)
}

files.core/internal/tool/history_result.go:
package tool

import (
	"context"
	"encoding/json"
	"errors"
	"strings"
	"unicode/utf8"

	"github.com/teatak/pudding-core/internal/store"
)

type resultReadOptions struct {
	Field  string  `json:"field"`
	Unit   string  `json:"unit"`
	Query  *string `json:"query"`
	Offset *int    `json:"offset"`
	Limit  *int    `json:"limit"`
}

// Read the saved tool result, not a re-execution of its command or a fresh file
// read. This also works within a running turn: results are committed before the
// next model request. No hidden provider state is exposed by this path.
func (r *BuiltinRunner) historyReadResult(ctx context.Context, out Result, sessionID string, ref ResultReference, options resultReadOptions) Result {
	if sessionID == "" || strings.TrimSpace(ref.TurnID) == "" || strings.TrimSpace(ref.CallID) == "" {
		return toolJSONError(out, "invalid_arguments", "result_ref requires turn_id, call_id and a session scope")
	}
	unit := options.Unit
	if unit == "" {
		unit = "chars"
	}
	offset, limit, maxLimit := 0, resultPageDefaultChars, resultPageMaxChars
	switch unit {
	case "chars":
	case "lines":
		limit, maxLimit = 40, 200
	case "items":
		limit, maxLimit = 20, 200
	default:
		return toolJSONError(out, "invalid_arguments", "unit must be chars, lines or items")
	}
	if options.Offset != nil {
		offset = *options.Offset
	}
	if options.Limit != nil {
		limit = *options.Limit
	}
	if offset < 0 || limit < 1 || limit > maxLimit {
		return toolJSONError(out, "invalid_arguments", "offset must be non-negative; limit is 1-8000 for chars or 1-200 for lines/items")
	}
	if options.Query != nil && (unit != "lines" || *options.Query == "" || utf8.RuneCountInString(*options.Query) > 500 || strings.ContainsAny(*options.Query, "\r\n")) {
		return toolJSONError(out, "invalid_arguments", "query requires unit=lines and a non-empty single-line literal of at most 500 characters; matching is case-sensitive")
	}
	if r.historyTurns == nil {
		return toolJSONError(out, "history_unavailable", "canonical tool result lookup is unavailable")
	}
	turn, err := r.historyTurns.GetConversationTurn(ctx, sessionID, ref.TurnID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			return toolJSONError(out, "result_not_found", "tool result not found in this session")
		}
		return toolJSONError(out, "read_failed", err.Error())
	}
	if turn == nil || turn.SessionID != sessionID || turn.ID != ref.TurnID {
		return toolJSONError(out, "result_not_found", "tool result not found in this session")
	}
	var found *store.ContentPart
	for _, message := range turn.Messages {
		for i := range message.Parts {
			part := &message.Parts[i]
			if part.Type != store.ContentPartToolResult || part.CallID != ref.CallID {
				continue
			}
			if found != nil {
				return toolJSONError(out, "ambiguous_result", "multiple results have this call_id; cannot select a snapshot safely")
			}
			found = part
		}
	}
	if found == nil {
		return toolJSONError(out, "result_not_found", "tool result not found in this turn")
	}
	content := found.Content
	if options.Field != "" {
		var fields map[string]json.RawMessage
		if json.Unmarshal([]byte(content), &fields) != nil {
			return toolJSONError(out, "invalid_field", "original tool result is not a JSON object; omit field to read raw text")
		}
		value, exists := fields[options.Field]
		if !exists {
			return toolJSONError(out, "invalid_field", "field does not exist in the original tool result")
		}
		content = string(value)
		isString := len(value) > 0 && value[0] == '"'
		if unit == "lines" && !isString {
			return toolJSONError(out, "invalid_field", "unit=lines requires a string field; use unit=items for an array")
		}
		if isString && unit != "items" {
			_ = json.Unmarshal(value, &content)
		}
	}
	payload := map[string]any{
		"ok": true, "session_id": sessionID, "result_ref": ref,
		"tool": found.Name, "result_ok": found.Ok, "snapshot": true,
		"unit": unit, "offset": offset,
	}
	if options.Field != "" {
		payload["field"] = options.Field
	}
	if unit != "chars" {
		return resultRecordPage(ctx, out, payload, content, unit, options.Query, offset, limit)
	}
	runes := []rune(content)
	if offset > len(runes) {
		return toolJSONError(out, "invalid_offset", "offset exceeds the selected result's total_chars")
	}
	end := offset + min(limit, len(runes)-offset)
	payload["total_chars"], payload["content"] = len(runes), string(runes[offset:end])
	payload["has_more"] = end < len(runes)
	if end < len(runes) {
		payload["next_offset"] = end
	}
	return jsonToolResult(out, true, payload)
}

// Pages contain complete records, bounded by both count and encoded size.
// A filtered page keeps offsets in the original text, so the same positions can
// be used without query to inspect neighboring lines. No new result cache exists.
func resultRecordPage(ctx context.Context, out Result, payload map[string]any, content, unit string, query *string, offset, limit int) Result {
	var lines []string
	var items []json.RawMessage
	total := 0
	if unit == "items" {
		if !strings.HasPrefix(strings.TrimSpace(content), "[") || json.Unmarshal([]byte(content), &items) != nil {
			return toolJSONError(out, "invalid_field", "unit=items requires a JSON array, not a string containing JSON")
		}
		total = len(items)
	} else {
		lines = strings.SplitAfter(content, "\n")
		if lines[len(lines)-1] == "" {
			lines = lines[:len(lines)-1]
		}
		total = len(lines)
	}
	if offset > total {
		return toolJSONError(out, "invalid_offset", "offset exceeds the selected result's total_"+unit)
	}
	payload["total_"+unit] = total
	if query != nil {
		payload["query"] = *query
	}
	records := make([]json.RawMessage, 0, min(limit, total-offset))
	size, next := 2, total // JSON array brackets; offsets always refer to the original snapshot.
	for i := offset; i < total; i++ {
		if err := ctx.Err(); err != nil {
			return toolJSONError(out, "cancelled", err.Error())
		}
		if query != nil && !strings.Contains(lines[i], *query) {
			continue
		}
		if len(records) >= limit {
			next = i
			break
		}
		var record json.RawMessage
		if unit == "items" {
			// Compact whitespace outside strings without decoding numeric values.
			record = resultJSON(items[i])
		} else {
			record = resultJSON(map[string]any{"line": i + 1, "text": lines[i]})
		}
		recordSize := utf8.RuneCount(record)
		separator := 0
		if len(records) > 0 {
			separator = 1
		}
		if size+separator+recordSize > resultPageMaxChars {
			if len(records) == 0 {
				payload["ok"], payload["reason"] = false, "record_too_large"
				payload["offset"], payload["record_chars"] = i, recordSize
				payload["detail"] = "One complete record exceeds the 8000-character page budget. Use unit=chars for bounded fragments; its offset counts characters, not records."
				return jsonToolResult(out, false, payload)
			}
			next = i
			break
		}
		records = append(records, record)
		size += separator + recordSize
	}
	payload[unit], payload["has_more"] = records, next < total
	if next < total {
		payload["next_offset"] = next
	}
	return jsonToolResult(out, true, payload)
}

files.core/internal/tool/context_result.go:
package tool

import (
	"encoding/json"
	"strconv"
	"strings"
	"unicode/utf8"
)

const (
	modelResultMaxChars    = 12000
	modelResultHeadChars   = 6000
	modelResultTailChars   = 2000
	modelSearchMaxMatches  = 20
	resultPageDefaultChars = 4000
	resultPageMaxChars     = 8000
)

// ResultReference points to an immutable canonical tool result, never a live
// filesystem path or a provider-side cache. The lookup is scoped by sessionID.
type ResultReference struct {
	TurnID string `json:"turn_id"`
	CallID string `json:"call_id"`
}

// ModelResultContent builds a deterministic model-only view. Canonical history
// and UI results remain unchanged. Only shorten results when a reader is in the
// request's tool set; skill instructions and explicit readback pages stay intact.
func ModelResultContent(name string, ok bool, content, turnID, callID string, canRead bool) string {
	if IsPluginLoad(name) || name == SkillRead {
		return SkillReferenceOnly(name, ok, content)
	}
	if name == HistoryGetMessage {
		return content
	}
	ref := ResultReference{TurnID: turnID, CallID: callID}
	canRead = canRead && ref.TurnID != "" && ref.CallID != ""
	var fields map[string]json.RawMessage
	if name == FileSlice || name == FileSearch {
		if json.Unmarshal([]byte(content), &fields) == nil && fields != nil {
			switch name {
			case FileSlice:
				var numbered string
				if value := fields["numberedContent"]; len(value) > 0 && value[0] == '"' && json.Unmarshal(value, &numbered) == nil {
					delete(fields, "content")
				}
			case FileSearch:
				var matches []map[string]json.RawMessage
				if json.Unmarshal(fields["matches"], &matches) == nil {
					for _, match := range matches {
						if numberSearchExcerpt(match) {
							continue
						}
						var text, excerpt string
						if json.Unmarshal(match["text"], &text) == nil && json.Unmarshal(match["excerpt"], &excerpt) == nil && text == excerpt {
							delete(match, "excerpt")
						}
					}
					if canRead && len(matches) > modelSearchMaxMatches {
						matches = matches[:modelSearchMaxMatches]
						fields["result_ref"] = resultJSON(ref)
						fields["preview_only"] = resultJSON(true)
						fields["shown_matches"] = resultJSON(len(matches))
					}
					fields["matches"] = resultJSON(matches)
				}
			}
			content = jsonString(fields)
		}
	}
	if !canRead || utf8.RuneCountInString(content) <= modelResultMaxChars {
		return content
	}
	// Keep outcome metadata separate from excerpts so an error near the middle
	// cannot turn into apparent success. Excerpts are explicitly not full JSON or
	// complete source lines; read the original result before relying on omissions.
	preview := map[string]any{
		"ok": ok, "result_ref": ref, "preview_only": true,
		"view_chars": utf8.RuneCountInString(content),
	}
	if fields == nil {
		_ = json.Unmarshal([]byte(content), &fields)
	}
	for _, key := range []string{
		"scope", "path", "root", "projectRoot", "relativePath", "cwd", "start", "end", "lines", "origin", "order",
		"reason", "error", "detail", "hint", "errorKind", "field", "expected", "offset", "receivedBytes", "metric", "actual", "limit", "unit", "count", "allowedScopes", "projectRoots",
		"command", "exitCode", "signal", "timedOut", "cancelled", "execution", "sandboxKind", "sandboxDenied", "shell", "durationMs", "truncated", "stdoutTruncated", "stderrTruncated", "verificationKind", "verificationStatus", "verificationWarning", "diagnosticCount", "matchCount", "resultsCapped", "shown_matches",
	} {
		if value, exists := fields[key]; exists && len(value) <= 1024 {
			preview[key] = value
		}
	}
	if name == CommandRun && fields["stdout"] != nil && fields["stderr"] != nil {
		for _, key := range []string{"stdout", "stderr"} {
			var value string
			if json.Unmarshal(fields[key], &value) == nil {
				preview[key] = modelCommandOutputPreview(value)
			}
		}
		return jsonString(preview)
	}
	if name == FilePatch && ok {
		for _, key := range []string{"status", "fileCount", "additions", "deletions", "destructive", "warnings", "widgetID", "draftHash"} {
			if value, exists := fields[key]; exists && len(value) <= 1024 {
				preview[key] = value
			}
		}
		var files []patchFileView
		if json.Unmarshal(fields["files"], &files) == nil {
			shown := modelPatchFilePreviews(files)
			preview["files"] = shown
			preview["shown_files"] = len(shown)
		}
		return jsonString(preview)
	}
	var recovery map[string]json.RawMessage
	if json.Unmarshal(fields["recovery"], &recovery) == nil && recovery != nil {
		// Keep the exact candidate coordinates even when diagnostic source lines
		// require a preview. The canonical result remains the source for readback.
		coordinates := make(map[string]json.RawMessage)
		for _, key := range []string{"path", "hunk", "startLine", "fileLineCount", "exactMatchCount", "candidatesTruncated", "mismatch", "context"} {
			if value, exists := recovery[key]; exists && len(value) <= 1024 {
				coordinates[key] = value
			}
		}
		var candidates []map[string]json.RawMessage
		if json.Unmarshal(recovery["candidates"], &candidates) == nil {
			candidates = candidates[:min(len(candidates), patchRecoveryMaxCandidates)]
			for _, candidate := range candidates {
				for key, value := range candidate {
					if (key != "startLine" && key != "context") || len(value) > 1024 {
						delete(candidate, key)
					}
				}
			}
			coordinates["candidates"] = resultJSON(candidates)
		}
		if len(coordinates) > 0 {
			preview["recovery"] = coordinates
		}
		if name == FilePatch {
			return jsonString(preview)
		}
	}
	runes := []rune(content)
	preview["head"] = string(runes[:modelResultHeadChars])
	preview["tail"] = string(runes[len(runes)-modelResultTailChars:])
	return jsonString(preview)
}

type modelPatchFilePreview struct {
	patchFileView
	LineRangesTruncated bool `json:"lineRangesTruncated,omitempty"`
}

func modelPatchFilePreviews(files []patchFileView) []modelPatchFilePreview {
	shown := make([]modelPatchFilePreview, 0, len(files))
	budget := modelResultHeadChars / max(1, len(files))
	for _, file := range files {
		item := modelPatchFilePreview{patchFileView: file}
		low, high := 0, len(file.LineRanges)
		for low < high {
			count := (low + high + 1) / 2
			item.LineRanges = file.LineRanges[:count]
			item.LineRangesTruncated = count < len(file.LineRanges)
			if utf8.RuneCountInString(jsonString(item)) <= budget {
				low = count
			} else {
				high = count - 1
			}
		}
		item.LineRanges = file.LineRanges[:low]
		item.LineRangesTruncated = low < len(file.LineRanges)
		candidate := append(shown, item)
		if utf8.RuneCountInString(jsonString(candidate)) > modelResultHeadChars {
			break
		}
		shown = candidate
	}
	return shown
}

func modelCommandOutputPreview(value string) map[string]any {
	runes := []rune(value)
	headChars := modelCommandExcerptChars(runes, modelResultHeadChars/2, false)
	tailChars := modelCommandExcerptChars(runes[headChars:], modelResultTailChars/2, true)
	return map[string]any{
		"head": string(runes[:headChars]), "tail": string(runes[len(runes)-tailChars:]),
		"chars": len(runes), "omitted_chars": len(runes) - headChars - tailChars,
	}
}

// Budget the serialized strings as well as decoded text: quotes, backslashes,
// control characters and newlines must not inflate the model preview.
func modelCommandExcerptChars(runes []rune, budget int, tail bool) int {
	low, high := 0, min(len(runes), budget)
	for low < high {
		count := (low + high + 1) / 2
		excerpt := runes[:count]
		if tail {
			excerpt = runes[len(runes)-count:]
		}
		if utf8.RuneCountInString(jsonString(string(excerpt))) <= budget {
			low = count
		} else {
			high = count - 1
		}
	}
	return low
}

func numberSearchExcerpt(match map[string]json.RawMessage) bool {
	var start, end, line int
	var excerpt string
	if json.Unmarshal(match["lineStart"], &start) != nil || json.Unmarshal(match["lineEnd"], &end) != nil || json.Unmarshal(match["line"], &line) != nil || start < 1 || end < start || line < start || line > end {
		return false
	}
	value := match["excerpt"]
	if len(value) == 0 || value[0] != '"' || json.Unmarshal(value, &excerpt) != nil {
		return false
	}
	lines := strings.Split(excerpt, "\n")
	if len(lines) != end-start+1 {
		return false
	}
	var numbered strings.Builder
	for index, text := range lines {
		if index > 0 {
			numbered.WriteByte('\n')
		}
		numbered.WriteString(strconv.Itoa(start + index))
		numbered.WriteString(": ")
		numbered.WriteString(text)
	}
	match["numberedExcerpt"] = resultJSON(numbered.String())
	delete(match, "excerpt")
	// Search text is a shorter preview of the matching excerpt line. Remove it
	// only when the numbered body includes that evidence, including blank lines.
	var text string
	if json.Unmarshal(match["text"], &text) == nil && strings.HasPrefix(lines[line-start], text) {
		delete(match, "text")
	}
	return true
}

func resultJSON(value any) json.RawMessage {
	data, _ := json.Marshal(value)
	return data
}

files.core/internal/tool/history.go:
package tool

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/teatak/pudding-core/internal/store"
)

const (
	historySearchDefaultLimit       = 10
	historySearchMaxLimit           = 30
	historySearchMaxBytes           = 20 * 1024
	historySearchPerMessageMaxBytes = 1024
	historyGetMessageMaxBytes       = 128 * 1024
	historyGetMessagePartMaxBytes   = 32 * 1024
)

func (r *BuiltinRunner) historySearch(ctx context.Context, call Call) Result {
	out := Result{CallID: call.CallID, Name: call.Name}
	var args struct {
		Query     string `json:"query"`
		SessionID string `json:"session_id"`
		Limit     int    `json:"limit"`
	}
	if len(call.Args) > 0 {
		if err := json.Unmarshal(call.Args, &args); err != nil {
			out.Ok = false
			out.Content = "invalid arguments: " + err.Error()
			return out
		}
	}
	query := strings.TrimSpace(args.Query)
	if query == "" {
		return jsonToolResult(out, false, map[string]any{
			"ok":        false,
			"reason":    "missing_query",
			"user_hint": "query cannot be empty.",
		})
	}
	if r.history == nil {
		return jsonToolResult(out, false, map[string]any{
			"ok":        false,
			"reason":    "history_unavailable",
			"user_hint": "history search is not enabled in this environment.",
		})
	}
	sessionID := strings.TrimSpace(args.SessionID)
	if sessionID == "" {
		sessionID = strings.TrimSpace(call.SessionID)
	}
	if sessionID == "" {
		return jsonToolResult(out, false, map[string]any{
			"ok":        false,
			"reason":    "missing_session_id",
			"user_hint": "history_search needs a session_id when there is no current session.",
		})
	}
	limit := args.Limit
	if limit <= 0 {
		limit = historySearchDefaultLimit
	}
	if limit > historySearchMaxLimit {
		limit = historySearchMaxLimit
	}
	hits, err := r.history.SearchMessages(ctx, store.MessageSearchInput{
		SessionID: sessionID,
		Query:     query,
		Limit:     limit,
	})
	if err != nil {
		reason := "search_failed"
		hint := ""
		if errors.Is(err, store.ErrHistorySearchUnavailable) {
			reason = "history_unavailable"
			hint = "history search requires a build with SQLite FTS5 enabled."
		}
		payload := map[string]any{
			"ok":     false,
			"reason": reason,
			"error":  err.Error(),
		}
		if hint != "" {
			payload["user_hint"] = hint
		}
		return jsonToolResult(out, false, payload)
	}
	messages, truncated := historySearchMessagesPayload(hits, historySearchMaxBytes)
	payload := map[string]any{
		"ok":         true,
		"query":      query,
		"session_id": sessionID,
		"hit_count":  len(hits),
		"messages":   messages,
	}
	if truncated {
		payload["truncated"] = true
		payload["truncate_hint"] = "The response was truncated by the byte limit; retry with a lower limit or more specific query."
	}
	return jsonToolResult(out, true, payload)
}

func (r *BuiltinRunner) historyGetMessage(ctx context.Context, call Call) Result {
	out := Result{CallID: call.CallID, Name: call.Name}
	var args struct {
		MessageID string           `json:"message_id"`
		SessionID string           `json:"session_id"`
		ResultRef *ResultReference `json:"result_ref"`
		resultReadOptions
	}
	if !json.Valid(call.Args) {
		return toolJSONError(out, "invalid_arguments", "arguments must be one JSON object")
	}
	decoder := json.NewDecoder(strings.NewReader(string(call.Args)))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&args); err != nil {
		return toolJSONError(out, "invalid_arguments", err.Error())
	}
	if args.ResultRef != nil {
		if strings.TrimSpace(args.MessageID) != "" {
			return toolJSONError(out, "invalid_arguments", "pass either message_id or result_ref, not both")
		}
		sessionID := strings.TrimSpace(args.SessionID)
		if sessionID == "" {
			sessionID = strings.TrimSpace(call.SessionID)
		}
		return r.historyReadResult(ctx, out, sessionID, *args.ResultRef, args.resultReadOptions)
	}
	if args.resultReadOptions != (resultReadOptions{}) {
		return toolJSONError(out, "invalid_arguments", "field, unit, query, offset and limit require result_ref")
	}
	messageID := strings.TrimSpace(args.MessageID)
	if messageID == "" {
		return jsonToolResult(out, false, map[string]any{
			"ok":        false,
			"reason":    "missing_message_id",
			"user_hint": "message_id cannot be empty.",
		})
	}
	if r.historyMessages == nil {
		return jsonToolResult(out, false, map[string]any{
			"ok":        false,
			"reason":    "history_unavailable",
			"user_hint": "history message lookup is not enabled in this environment.",
		})
	}
	sessionID := strings.TrimSpace(args.SessionID)
	if sessionID == "" {
		sessionID = strings.TrimSpace(call.SessionID)
	}
	if sessionID == "" {
		return jsonToolResult(out, false, map[string]any{
			"ok":        false,
			"reason":    "missing_session_id",
			"user_hint": "history_get_message needs a session_id when there is no current session.",
		})
	}
	msg, err := r.historyMessages.GetMessage(ctx, sessionID, messageID)
	if err != nil {
		reason := "fetch_message_failed"
		if errors.Is(err, store.ErrNotFound) {
			reason = "message_not_found"
		}
		return jsonToolResult(out, false, map[string]any{
			"ok":         false,
			"reason":     reason,
			"session_id": sessionID,
			"message_id": messageID,
			"error":      err.Error(),
		})
	}
	if msg == nil {
		return jsonToolResult(out, false, map[string]any{
			"ok":         false,
			"reason":     "message_not_found",
			"session_id": sessionID,
			"message_id": messageID,
		})
	}
	payload, truncated := historyGetMessagePayload(msg, historyGetMessageMaxBytes)
	if truncated {
		payload["truncated"] = true
		payload["truncate_hint"] = "The response was truncated by the byte limit; use builtin_history_search for a narrower target."
	}
	return jsonToolResult(out, true, payload)
}

func historyGetMessagePayload(msg *store.Message, maxBytes int) (map[string]any, bool) {
	if msg == nil {
		return map[string]any{"ok": false, "reason": "message_not_found"}, false
	}
	text, textTruncated := truncateUTF8Bytes(msg.Text, maxBytes)
	parts, partsTruncated := historyPartsPayload(msg.Parts)
	payload := map[string]any{
		"ok":         true,
		"message_id": msg.ID,
		"ref":        "@message(" + msg.ID + ")",
		"session_id": msg.SessionID,
		"turn_id":    msg.TurnID,
		"role":       msg.Role,
		"kind":       msg.Kind,
		"text":       text,
		"created_at": msg.CreatedAt.UTC().Format(time.RFC3339),
	}
	if len(parts) > 0 {
		payload["parts"] = parts
	}
	if msg.ClientMessageID != "" {
		payload["client_message_id"] = msg.ClientMessageID
	}
	if msg.Interrupted {
		payload["interrupted"] = true
	}
	if len(msg.Metadata) > 0 {
		payload["metadata"] = msg.Metadata
	}
	if attachments := store.AttachmentsFromParts(msg.Parts); len(attachments) > 0 {
		payload["attachments"] = historyAttachmentPayload(attachments)
	}
	if folders := store.LocalFoldersFromParts(msg.Parts); len(folders) > 0 {
		payload["local_folders"] = historyLocalFolderPayload(folders)
	}
	return payload, textTruncated || partsTruncated
}

func historyPartsPayload(parts []store.ContentPart) ([]store.ContentPart, bool) {
	out := store.CloneContentParts(parts)
	truncated := false
	for i := range out {
		var textTruncated bool
		out[i].Text, textTruncated = truncateUTF8Bytes(out[i].Text, historyGetMessagePartMaxBytes)
		truncated = truncated || textTruncated
		out[i].Content, textTruncated = truncateUTF8Bytes(out[i].Content, historyGetMessagePartMaxBytes)
		truncated = truncated || textTruncated
		out[i].AudioTranscript, textTruncated = truncateUTF8Bytes(out[i].AudioTranscript, historyGetMessagePartMaxBytes)
		truncated = truncated || textTruncated
	}
	return out, truncated
}

func historySearchMessagesPayload(hits []*store.Message, maxBytes int) ([]map[string]any, bool) {
	used := 0
	out := make([]map[string]any, 0, len(hits))
	for _, msg := range hits {
		if msg == nil {
			continue
		}
		text, textTruncated := truncateUTF8Bytes(msg.Text, historySearchPerMessageMaxBytes)
		entry := map[string]any{
			"id":         msg.ID,
			"ref":        "@message(" + msg.ID + ")",
			"session_id": msg.SessionID,
			"role":       msg.Role,
			"text":       text,
			"ts":         msg.CreatedAt.UTC().Format(time.RFC3339),
		}
		if msg.Kind != "" {
			entry["kind"] = msg.Kind
		}
		if textTruncated {
			entry["truncated"] = true
		}
		if attachments := store.AttachmentsFromParts(msg.Parts); len(attachments) > 0 {
			entry["attachments"] = historyAttachmentPayload(attachments)
		}
		entryBytes := len(msg.ID) + len(msg.SessionID) + len(msg.Role) + len(text) + 128
		if used+entryBytes > maxBytes {
			return out, true
		}
		used += entryBytes
		out = append(out, entry)
	}
	return out, false
}

func historyAttachmentPayload(attachments []store.Attachment) []map[string]any {
	out := make([]map[string]any, 0, len(attachments))
	for _, attachment := range attachments {
		item := map[string]any{
			"id":   attachment.ID,
			"name": attachment.Name,
			"mime": attachment.MIME,
			"size": attachment.Size,
		}
		if attachment.AttachmentKey != "" {
			item["attachment_key"] = attachment.AttachmentKey
		}
		if attachment.URL != "" {
			item["url"] = attachment.URL
		}
		if attachment.SourcePath != "" {
			item["source_path"] = attachment.SourcePath
		}
		if attachment.CreatedAt != "" {
			item["created_at"] = attachment.CreatedAt
		}
		if attachment.AudioTranscript != "" {
			item["audio_transcript"] = attachment.AudioTranscript
		}
		out = append(out, item)
	}
	return out
}

func historyLocalFolderPayload(folders []store.LocalFolder) []map[string]any {
	out := make([]map[string]any, 0, len(folders))
	for _, folder := range folders {
		item := map[string]any{
			"id":   folder.ID,
			"name": folder.Name,
			"path": folder.Path,
		}
		if folder.Origin != "" {
			item["origin"] = folder.Origin
		}
		out = append(out, item)
	}
	return out
}

func truncateUTF8Bytes(s string, max int) (string, bool) {
	if max <= 0 || len(s) <= max {
		return s, false
	}
	cut := 0
	for idx := range s {
		if idx > max {
			break
		}
		cut = idx
	}
	if cut <= 0 {
		return "...(truncated)", true
	}
	return s[:cut] + "...(truncated)", true
}

func jsonToolResult(out Result, ok bool, payload map[string]any) Result {
	b, err := json.Marshal(payload)
	if err != nil {
		out.Ok = false
		out.Content = fmt.Sprintf("marshal result: %v", err)
		return out
	}
	out.Ok = ok
	out.Content = string(b)
	if messages, ok := payload["messages"].([]map[string]any); ok {
		out.SummaryKind = SummaryReturnedItems
		out.SummaryCount = len(messages)
	} else if ok {
		out.SummaryKind = SummaryReturnedFields
		out.SummaryCount = len(payload)
	}
	return out
}

files.core/internal/tool/history_result_test.g:
package tool

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"testing"
	"unicode/utf8"

	"github.com/teatak/pudding-core/internal/store"
)

type fakeResultHistory struct {
	fakeHistorySource
	turn *store.ConversationTurn
}

func (f *fakeResultHistory) GetConversationTurn(_ context.Context, sessionID, turnID string) (*store.ConversationTurn, error) {
	if sessionID != f.turn.SessionID || turnID != f.turn.ID {
		return nil, store.ErrNotFound
	}
	return f.turn, nil
}

func TestResultReadSelectsOriginalFieldsAndDetectsAmbiguousCalls(t *testing.T) {
	raw := `{"ok":true,"content":"原始正文🙂","matches":[{"line":2,"text":"命中"}]}`
	src := &fakeResultHistory{turn: &store.ConversationTurn{ID: "t1", SessionID: "s1", Messages: []*store.Message{{
		Parts: []store.ContentPart{{Type: store.ContentPartToolResult, CallID: "c1", Name: FileSearch, Ok: true, Content: raw}},
	}}}}
	runner := NewBuiltinRunner(WithHistorySearch(src))
	read := func(fields map[string]any) Result {
		fields["result_ref"] = ResultReference{TurnID: "t1", CallID: "c1"}
		args, _ := json.Marshal(fields)
		return runner.Call(context.Background(), Call{SessionID: "s1", Name: HistoryGetMessage, Args: args})
	}
	for _, tc := range []struct{ field, want string }{
		{"", raw}, {"content", "原始正文🙂"}, {"matches", `[{"line":2,"text":"命中"}]`}, {"ok", "true"},
	} {
		args := map[string]any{}
		if tc.field != "" {
			args["field"] = tc.field
		}
		result := read(args)
		if !result.Ok {
			t.Fatal(result.Content)
		}
		page := decodeToolResult(t, result)
		if page["content"] != tc.want || page["has_more"] != false {
			t.Fatalf("unexpected field page: %+v", page)
		}
		if _, exists := page["next_offset"]; exists {
			t.Fatal("EOF must not advertise a next page")
		}
	}
	end := read(map[string]any{"field": "content", "offset": 5})
	if !end.Ok || decodeToolResult(t, end)["content"] != "" {
		t.Fatalf("empty EOF page failed: %+v", end)
	}
	src.turn.Messages[0].Parts = append(src.turn.Messages[0].Parts, src.turn.Messages[0].Parts[0])
	result := read(map[string]any{})
	if result.Ok || decodeToolResult(t, result)["reason"] != "ambiguous_result" {
		t.Fatalf("ambiguous snapshot accepted: %+v", result)
	}
}

func TestResultReadPlainTextAndMissingSource(t *testing.T) {
	src := &fakeResultHistory{turn: &store.ConversationTurn{ID: "t1", SessionID: "s1", Messages: []*store.Message{{
		Parts: []store.ContentPart{{Type: store.ContentPartToolResult, CallID: "c1", Content: "plain text"}},
	}}}}
	call := Call{SessionID: "s1", Name: HistoryGetMessage, Args: json.RawMessage(`{"result_ref":{"turn_id":"t1","call_id":"c1"}}`)}
	result := NewBuiltinRunner(WithHistorySearch(src)).Call(context.Background(), call)
	if !result.Ok || decodeToolResult(t, result)["content"] != "plain text" {
		t.Fatal(result.Content)
	}
	result = NewBuiltinRunner().Call(context.Background(), call)
	if result.Ok || decodeToolResult(t, result)["reason"] != "history_unavailable" {
		t.Fatal(result.Content)
	}
}

func TestHistoryGetMessageRequiresExactlyOneSelector(t *testing.T) {
	runner := NewBuiltinRunner(WithHistorySearch(&fakeResultHistory{turn: &store.ConversationTurn{ID: "t1", SessionID: "s1"}}))
	for name, args := range map[string]string{
		"missing selector": `{}`,
		"both selectors":   `{"message_id":"m1","result_ref":{"turn_id":"t1","call_id":"c1"}}`,
	} {
		t.Run(name, func(t *testing.T) {
			result := runner.Call(context.Background(), Call{SessionID: "s1", Name: HistoryGetMessage, Args: json.RawMessage(args)})
			if result.Ok {
				t.Fatalf("invalid selector accepted: %s", args)
			}
			payload := decodeToolResult(t, result)
			if name == "missing selector" && payload["reason"] != "missing_message_id" {
				t.Fatalf("missing selector reason = %v", payload["reason"])
			}
			if name == "both selectors" && payload["reason"] != "invalid_arguments" {
				t.Fatalf("both selectors reason = %v", payload["reason"])
			}
		})
	}
}

func TestResultReadFocusedLinesAndItems(t *testing.T) {
	log := strings.Repeat("routine output\n", 300) + "ERROR 中文🙂\r\n" + strings.Repeat("routine output\n", 300) + "ERROR second"
	raw, _ := json.Marshal(map[string]any{"stdout": log, "matches": []any{map[string]any{"line": 5, "text": "first"}, map[string]any{"line": 9, "text": "second"}}})
	src := &fakeResultHistory{turn: &store.ConversationTurn{ID: "t1", SessionID: "s1", Messages: []*store.Message{{
		Parts: []store.ContentPart{{Type: store.ContentPartToolResult, CallID: "c1", Ok: false, Content: string(raw)}},
	}}}}
	runner := NewBuiltinRunner(WithHistorySearch(src))
	read := func(extra string) Result {
		return runner.Call(context.Background(), Call{SessionID: "s1", Name: HistoryGetMessage, Args: json.RawMessage(`{"result_ref":{"turn_id":"t1","call_id":"c1"},` + extra + `}`)})
	}
	result := read(`"field":"stdout","unit":"lines","query":"ERROR","limit":1`)
	page := decodeToolResult(t, result)
	if !result.Ok || page["result_ok"] != false || page["total_lines"] != float64(602) || page["has_more"] != true || page["next_offset"] != float64(601) {
		t.Fatalf("unexpected search page: %s", result.Content)
	}
	lines := page["lines"].([]any)
	if len(lines) != 1 || lines[0].(map[string]any)["line"] != float64(301) || lines[0].(map[string]any)["text"] != "ERROR 中文🙂\r\n" {
		t.Fatalf("lost exact line or source position: %s", result.Content)
	}
	if len(result.Content) >= len(log)/4 {
		t.Fatal("focused search still returned the routine log")
	}
	result = read(`"field":"stdout","unit":"lines","query":"ERROR","offset":601,"limit":1`)
	page = decodeToolResult(t, result)
	if !result.Ok || page["has_more"] != false || page["lines"].([]any)[0].(map[string]any)["line"] != float64(602) {
		t.Fatalf("search continuation lost a match: %s", result.Content)
	}
	result = read(`"field":"stdout","unit":"lines","offset":300,"limit":1`)
	if !result.Ok || decodeToolResult(t, result)["lines"].([]any)[0].(map[string]any)["text"] != "ERROR 中文🙂\r\n" {
		t.Fatal(result.Content)
	}
	result = read(`"field":"matches","unit":"items","offset":1,"limit":1`)
	page = decodeToolResult(t, result)
	if !result.Ok || page["total_items"] != float64(2) || page["has_more"] != false || page["items"].([]any)[0].(map[string]any)["text"] != "second" {
		t.Fatalf("array record was not preserved: %s", result.Content)
	}
	for _, extra := range []string{
		`"field":"stdout","query":"ERROR"`,
		`"field":"stdout","unit":"lines","query":""`,
		`"field":"stdout","unit":"lines","query":"a\nb"`,
		`"field":"stdout","unit":"lines","limit":201`,
		`"field":"stdout","unit":"lines","offset":603`,
		`"field":"stdout","unit":"items"`,
		`"field":"matches","unit":"lines"`,
		`"field":"matches","unit":"items","query":"first"`,
		`"field":"stdout","unit":"bytes"`,
	} {
		if result := read(extra); result.Ok {
			t.Fatalf("invalid focused read accepted: %s", extra)
		}
	}
}

func TestResultReadCompleteRecordsRespectBudget(t *testing.T) {
	for _, unit := range []string{"lines", "items"} {
		t.Run(unit, func(t *testing.T) {
			var source strings.Builder
			var items []string
			for i := 0; i < 12; i++ {
				line := fmt.Sprintf("%d %s\n", i, strings.Repeat("中文🙂", 600))
				source.WriteString(line)
				items = append(items, line)
			}
			content := source.String()
			if unit == "items" {
				raw, _ := json.Marshal(items)
				content = string(raw)
			}
			src := &fakeResultHistory{turn: &store.ConversationTurn{ID: "t1", SessionID: "s1", Messages: []*store.Message{{
				Parts: []store.ContentPart{{Type: store.ContentPartToolResult, CallID: "c1", Content: content}},
			}}}}
			runner := NewBuiltinRunner(WithHistorySearch(src))
			var restored []string
			offset := 0
			for {
				args, _ := json.Marshal(map[string]any{"result_ref": ResultReference{TurnID: "t1", CallID: "c1"}, "unit": unit, "offset": offset, "limit": 200})
				result := runner.Call(context.Background(), Call{SessionID: "s1", Name: HistoryGetMessage, Args: args})
				if !result.Ok {
					t.Fatal(result.Content)
				}
				page := decodeToolResult(t, result)
				encoded, _ := json.Marshal(page[unit])
				if utf8.RuneCount(encoded) > resultPageMaxChars {
					t.Fatal("encoded records exceeded the page budget")
				}
				for _, record := range page[unit].([]any) {
					if unit == "lines" {
						restored = append(restored, record.(map[string]any)["text"].(string))
					} else {
						restored = append(restored, record.(string))
					}
				}
				if page["has_more"] == false {
					break
				}
				next := int(page["next_offset"].(float64))
				if next <= offset || len(page[unit].([]any)) >= len(items) {
					t.Fatal("budget was ignored or pagination did not advance")
				}
				offset = next
			}
			if strings.Join(restored, "") != source.String() {
				t.Fatal("paging split, lost or duplicated a complete record")
			}
		})
	}
}

func TestResultReadRecordEdges(t *testing.T) {
	for _, tc := range []struct {
		name, raw, extra, reason string
	}{
		{name: "empty text", raw: `{"text":""}`, extra: `"field":"text","unit":"lines"`},
		{name: "empty array", raw: `{"data":[]}`, extra: `"field":"data","unit":"items"`},
		{name: "no matches", raw: `{"text":"ordinary\ntext\n"}`, extra: `"field":"text","unit":"lines","query":"ERROR"`},
		{name: "case sensitive", raw: `{"text":"error\n"}`, extra: `"field":"text","unit":"lines","query":"ERROR"`},
		{name: "line EOF", raw: `{"text":"first\nlast"}`, extra: `"field":"text","unit":"lines","offset":2`},
		{name: "array EOF", raw: `{"data":[1]}`, extra: `"field":"data","unit":"items","offset":1`},
		{name: "string is not array", raw: `{"data":"[1,2]"}`, extra: `"field":"data","unit":"items"`, reason: "invalid_field"},
		{name: "object is not array", raw: `{"data":{}}`, extra: `"field":"data","unit":"items"`, reason: "invalid_field"},
		{name: "null is not array", raw: `{"data":null}`, extra: `"field":"data","unit":"items"`, reason: "invalid_field"},
		{name: "oversized line", raw: jsonString(map[string]any{"text": strings.Repeat("x", 8001)}), extra: `"field":"text","unit":"lines"`, reason: "record_too_large"},
		{name: "oversized item", raw: jsonString(map[string]any{"data": []string{strings.Repeat("x", 8001)}}), extra: `"field":"data","unit":"items"`, reason: "record_too_large"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			src := &fakeResultHistory{turn: &store.ConversationTurn{ID: "t1", SessionID: "s1", Messages: []*store.Message{{
				Parts: []store.ContentPart{{Type: store.ContentPartToolResult, CallID: "c1", Content: tc.raw}},
			}}}}
			result := NewBuiltinRunner(WithHistorySearch(src)).Call(context.Background(), Call{SessionID: "s1", Name: HistoryGetMessage,
				Args: json.RawMessage(`{"result_ref":{"turn_id":"t1","call_id":"c1"},` + tc.extra + `}`)})
			page := decodeToolResult(t, result)
			if tc.reason != "" {
				if result.Ok || page["reason"] != tc.reason {
					t.Fatal(result.Content)
				}
				return
			}
			if !result.Ok || page["has_more"] != false {
				t.Fatal(result.Content)
			}
			if _, exists := page["next_offset"]; exists {
				t.Fatal("empty/EOF result must not offer another page")
			}
			if records := page[page["unit"].(string)].([]any); len(records) != 0 {
				t.Fatalf("expected empty page: %s", result.Content)
			}
		})
	}
}

func TestResultReadItemsPreserveNumbersAndLinesPreserveBlankEndings(t *testing.T) {
	ctx := context.Background()
	for _, tc := range []struct{ unit, content, want string }{
		{"items", `[{ "number": 9007199254740993, "text":"a\"b" }, null, true, [1,2]]`, `[{"number":9007199254740993,"text":"a\"b"},null,true,[1,2]]`},
		{"lines", "\n\r\nlast\n", `[{"line":1,"text":"\n"},{"line":2,"text":"\r\n"},{"line":3,"text":"last\n"}]`},
	} {
		out := resultRecordPage(ctx, Result{}, map[string]any{}, tc.content, tc.unit, nil, 0, 20)
		var page map[string]json.RawMessage
		if !out.Ok || json.Unmarshal([]byte(out.Content), &page) != nil || string(page[tc.unit]) != tc.want {
			t.Fatalf("record contents changed: %s", out.Content)
		}
	}
	ctx, cancel := context.WithCancel(ctx)
	cancel()
	result := resultRecordPage(ctx, Result{}, map[string]any{}, "text\n", "lines", nil, 0, 20)
	if result.Ok || decodeToolResult(t, result)["reason"] != "cancelled" {
		t.Fatal(result.Content)
	}
}

